INSERT INTO listings (listing_id, category, title, city, district, community, price_minor, area_sqm, rooms, metro, attrs_json, description, photos_json, agent_id, owner_user_id, status, listed_at) VALUES ('lst_rscam_0001', 'secondhand', 'Sonar A7M3 Full-Frame Mirrorless Body | First-Hand Personal Ownership', 'Guangzhou City', 'Haizhu District', 'Kecun', 800000, NULL, NULL, 'Line 3·Kecun Station', '{"condition_grade":"Good","shutter_count":18420,"serial_no":"SNR-A7M3-3521","verification_code":"VRF-RSCAM-3521G","original_invoice":true,"platform_fee_minor":20000,"escrow_required":true}', 'Purchased at the end of 2025, with all functions testing normally; slight marks from a quick-release tripod plate on the bottom, with no impact marks on the screen or mount. Includes the original battery, charger, body cap, and original invoice. Platform-escrowed orders only.', '["Front of body and serial number","Signs of use on bottom","Screen powered on","Mount and sensor","Shutter count screenshot","Redacted page of original invoice"]', 'agt_rscam_1', 'usr_zhan_peng', 'active', '2026-06-15T09:00:00+08:00');
INSERT INTO listings (listing_id, category, title, city, district, community, price_minor, area_sqm, rooms, metro, attrs_json, description, photos_json, agent_id, owner_user_id, status, listed_at) VALUES ('lst_rscam_0002', 'secondhand', 'Same-City A7M3 Body | High Shutter Count, No Invoice', 'Guangzhou City', 'Baiyun District', 'Sanyuanli', 715000, NULL, NULL, 'Line 2·Sanyuanli Station', '{"condition_grade":"Fair","shutter_count":61200,"original_invoice":false,"escrow_required":true}', 'The body functions normally, but the grip leather is lifting; the seller cannot provide the original invoice. The price includes one third-party battery.', '["Front of body","Grip leather","Shutter count"]', 'agt_rscam_1', NULL, 'active', '2026-06-12T10:00:00+08:00');
INSERT INTO listings (listing_id, category, title, city, district, community, price_minor, area_sqm, rooms, metro, attrs_json, description, photos_json, agent_id, owner_user_id, status, listed_at) VALUES ('lst_rscam_0003', 'secondhand', 'A7M3 Low-Shutter-Count Kit | Original Battery and Packaging Included', 'Guangzhou City', 'Tianhe District', 'Gangding', 835000, NULL, NULL, 'Line 3·Gangding Station', '{"condition_grade":"Excellent","shutter_count":9600,"original_invoice":true,"escrow_required":true}', 'Low-shutter-count personal camera; the packaging and body numbers match. No obvious edge wear exposing the underlying material. Supports shipment after platform inspection.', '["Six sides of body","Shutter count","Box label number"]', 'agt_rscam_1', NULL, 'active', '2026-06-11T10:00:00+08:00');
