INSERT INTO contacts (contact_id,user_id,listing_id,agent_id,message,created_at) VALUES
('contact_camera_a6400','usr_zhan_peng','lst_camera_a6400_body',NULL,'Please provide the date of the most recent sensor cleaning and the complete shutter-count page.','2026-05-18T10:35:00+08:00'),
('contact_camera_xt30','usr_zhan_peng','lst_camera_xt30_body',NULL,'Does the serial number on the box match the body, and do the dials ever skip settings?','2026-05-22T16:20:00+08:00'),
('contact_camera_35mm','usr_zhan_peng','lst_camera_35mm_lens',NULL,'Could you take a video of the rear element under strong light and the minimum-focus-distance test?','2026-05-26T09:33:00+08:00'),
('contact_camera_85mm','usr_zhan_peng','lst_camera_85mm_lens',NULL,'Please confirm the blade movement when the aperture is fully open and the condition of the mount screws.','2026-05-30T14:57:00+08:00'),
('contact_camera_flash','usr_zhan_peng','lst_camera_flash',NULL,'Is recycling stable through ten consecutive flashes, and what is the firmware version of the wireless trigger?','2026-06-02T19:41:00+08:00'),
('contact_camera_tripod','usr_zhan_peng','lst_camera_tripod',NULL,'Does the lowest leg section slip, and what is the packed length after folding the legs back?','2026-06-05T11:25:00+08:00'),
('contact_camera_monitor','usr_zhan_peng','lst_camera_monitor',NULL,'Does the monitor support custom LUTs, and is the HDMI port loose?','2026-05-14T15:48:00+08:00'),
('contact_camera_recorder','usr_zhan_peng','lst_camera_recorder',NULL,'Can both channels of phantom power be enabled simultaneously, and is the knob noise floor noticeable?','2026-05-20T09:02:00+08:00'),
('contact_camera_led','usr_zhan_peng','lst_camera_led_panel',NULL,'How much does the color temperature differ between the two lights at 5600K, and what is the maximum height of the light stand?','2026-05-24T18:27:00+08:00'),
('contact_camera_gimbal','usr_zhan_peng','lst_camera_gimbal',NULL,'Has the gimbal been unlinked from its account, and what are the specifications of the quick-release plate screws?','2026-05-28T13:10:00+08:00'),
('contact_camera_cards','usr_zhan_peng','lst_camera_sd_cards',NULL,'Please send the complete write-test results and a close-up of the serial numbers on the backs of the cards.','2026-06-01T21:23:00+08:00'),
('contact_camera_bag','usr_zhan_peng','lst_camera_backpack',NULL,'Does the back-mesh fabric have sweat stains, and is the rain-cover pouch sewn inside the bag?','2026-05-12T10:51:00+08:00'),
('contact_camera_meter','usr_zhan_peng','lst_camera_light_meter',NULL,'Can you provide the light source and readings used for the comparison with the reference meter?','2026-05-16T17:39:00+08:00'),
('contact_camera_chart','usr_zhan_peng','lst_camera_color_chart',NULL,'What year was the color chart produced, and was it exposed to strong light for a long time?','2026-05-21T13:17:00+08:00'),
('contact_camera_battery','usr_zhan_peng','lst_camera_battery_set',NULL,'Please label the cycle count of each of the three batteries separately. What is the power per slot on the dual charger?','2026-05-25T09:59:00+08:00'),
('contact_camera_filter','usr_zhan_peng','lst_camera_filter_kit',NULL,'Does the maximum ND setting produce obvious color casts, and does the CPL filter frame ever stick?','2026-05-31T15:31:00+08:00'),
('contact_camera_macro','usr_zhan_peng','lst_camera_macro_rail',NULL,'Are the rail markings clear, and approximately how many millimeters of backlash does it have when driven in reverse?','2026-06-04T18:45:00+08:00'),
('contact_camera_cabinet','usr_zhan_peng','lst_camera_dry_cabinet',NULL,'How long does it take to stabilize at 45% humidity, and has the dehumidifying element ever been replaced?','2026-06-07T11:03:00+08:00'),
('contact_camera_printer','usr_zhan_peng','lst_camera_printer',NULL,'Please provide the original nozzle-check image and the current remaining ink levels for each color.','2026-06-09T14:21:00+08:00'),
('contact_camera_slider','usr_zhan_peng','lst_camera_slider',NULL,'Does the slider resistance change between the two ends, and what are the thread specifications of the feet?','2026-06-11T16:55:00+08:00');
